#include <mutex>
#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

class OpenAIHttpTransport final : public IAgentHttpTransport
{
public:
    bool post(AgentHttpRequest request, EventFn event) override
    {
        cancel();
        auto state = std::make_shared<State>();
        state->event = std::move(event);
        m_state = state;

        auto http = Slic3r::Http::post(std::move(request.url));
        http.header("Authorization", request.authorization)
            .header("Idempotency-Key", request.idempotency_key)
            .header("Content-Type", "application/json")
            .header("Accept", "text/event-stream")
            .tls_verify(true)
            .timeout_connect(request.connect_timeout_seconds)
            .timeout_max(request.request_timeout_seconds)
            .size_limit(request.response_size_limit)
            .set_post_body(request.body)
            .on_progress([weak = std::weak_ptr<State>(state)](Slic3r::Http::Progress progress, bool& should_cancel) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                should_cancel = locked->cancelled;
                if (locked->cancelled || progress.buffer.size() <= locked->seen)
                    return;
                std::string delta = progress.buffer.substr(locked->seen);
                locked->seen = progress.buffer.size();
                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, std::move(delta), {}, 0});
            })
            .on_complete([weak = std::weak_ptr<State>(state)](std::string body, unsigned status) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                if (locked->cancelled)
                    return;
                if (body.size() > locked->seen)
                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, body.substr(locked->seen), {}, status});
                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Complete, {}, {}, status});
            })
            .on_error([weak = std::weak_ptr<State>(state)](std::string, std::string error, unsigned status) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                if (!locked->cancelled)
                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Error, {}, std::move(error), status});
            });
        state->http = http.perform();
        return state->http != nullptr;
    }

    void cancel() override
    {
        const auto state = std::move(m_state);
        if (!state)
            return;
        Slic3r::Http::Ptr http;
        {
            std::lock_guard<std::mutex> guard(state->mutex);
            state->cancelled = true;
            http = state->http;
        }
        if (http)
            http->cancel();
    }

private:
    struct State
    {
        std::mutex       mutex;
        EventFn          event;
        Slic3r::Http::Ptr http;
        std::size_t      seen{0};
        bool             cancelled{false};
    };
    std::shared_ptr<State> m_state;
};

} // namespace

std::unique_ptr<IAgentHttpTransport> make_openai_http_transport()
{
    return std::make_unique<OpenAIHttpTransport>();
}

} // namespace Slic3r::GUI::JusPrin::Agent
---SETUP-HPP---
#pragma once

// Provider credential setup for the Agent dock.
//
// Verifying a key and building the service that will use it are the same act
// here: the check runs one real request through the provider adapter the
// Agent goes on to use, so a key that passes is a key the Agent is already
// talking through, and the round-trip the user is shown is the one that
// actually happened. Nothing separate has to be kept in sync with it.
//
// GUI-free and poll-driven, mirroring IAgentService: transport callbacks only
// queue work, and the owner releases outcomes from poll() on the GUI thread.
// Persistence is injected, so this file never reaches AppConfig and stays
// linkable into the GUI-free contract tests.

#include "AgentService.hpp"
#include "OpenAIResponsesAgent.hpp"

#include <chrono>
#include <functional>
#include <memory>
#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin::Agent {

struct SetupCredentials
{
    std::string provider; // "openai"
    std::string api_key;
    std::string model;    // optional; empty keeps the adapter's default
    std::string endpoint; // optional; empty keeps the adapter's default
};

struct SetupOutcome
{
    bool            ok{false};
    AgentError      error;      // set when !ok
    int             elapsed_ms{0};
    AgentServicePtr service;    // set when ok: verified, idle, ready to install
};

class IAgentSetupService
{
public:
    virtual ~IAgentSetupService() = default;

    virtual bool busy() const = 0;

    // Begins one verification. False when a check is already running, the
    // credentials are incomplete, or this build has no adapter for the
    // provider.
    virtual bool start_check(const SetupCredentials& credentials) = 0;
    virtual void cancel() = 0;

    // Releases at most one finished outcome; called from the owner's tick.
    virtual std::optional<SetupOutcome> poll() = 0;

    // Persists credentials that have just been verified. Reports failure
    // rather than pretending: a key that was not stored is a key the user
    // will have to enter again next launch, and they are told so.
    virtual bool commit(const SetupCredentials& credentials) = 0;
};

using AgentSetupServicePtr = std::shared_ptr<IAgentSetupService>;

// Providers this build can verify. The page offers the same list; the host
// checks anyway, so a page/host mismatch fails visibly instead of hanging.
bool setup_provider_supported(const std::string& provider);

class ProviderKeySetup final : public IAgentSetupService
{
public:
    using TransportFactory = std::function<std::unique_ptr<IAgentHttpTransport>()>;
    using CommitFn         = std::function<bool(const SetupCredentials&)>;
    using Clock            = std::function<std::chrono::steady_clock::time_point()>;

    // endpoint_override redirects the check the way JUSPRIN_OPENAI_ENDPOINT
    // redirects the live Agent, so a developer or a harness can point setup
    // at a stand-in instead of the real provider.
    ProviderKeySetup(TransportFactory transport,
                     CommitFn         commit,
                     std::string      endpoint_override = {},
                     Clock            clock             = {});
    ~ProviderKeySetup() override;

    bool                        busy() const override { return m_candidate != nullptr; }
    bool                        start_check(const SetupCredentials& credentials) override;
    void                        cancel() override;
    std::optional<SetupOutcome> poll() override;
    bool                        commit(const SetupCredentials& credentials) override;

private:
    int          elapsed_ms() const;
    SetupOutcome finish_ok();

    TransportFactory                      m_transport_factory;
    CommitFn                              m_commit;
    std::string                           m_endpoint_override;
    Clock                                 m_clock;
    AgentServicePtr                       m_candidate;
    std::chrono::steady_clock::time_point m_started{};
};

} // namespace Slic3r::GUI::JusPrin::Agent
---SETUP-CPP---
#include "AgentSetup.hpp"

#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

// The probe deliberately carries no project. A provider the user has not
// chosen yet must not receive their workspace merely to prove that a key
// works, so the request is a fixed sentence with an empty snapshot.
AgentRequest probe_request()
{
    AgentRequest request;
    request.request_id = "setup-key-check";
    request.user_text  = "Reply with the single word: ready.";
    return request;
}

} // namespace

bool setup_provider_supported(const std::string& provider) { return provider == "openai"; }

ProviderKeySetup::ProviderKeySetup(TransportFactory transport,
                                   CommitFn         commit,
                                   std::string      endpoint_override,
                                   Clock            clock)
    : m_transport_factory(std::move(transport)), m_commit(std::move(commit)),
      m_endpoint_override(std::move(endpoint_override)), m_clock(std::move(clock))
{
    if (!m_clock)
        m_clock = []() { return std::chrono::steady_clock::now(); };
}

ProviderKeySetup::~ProviderKeySetup() = default;

bool ProviderKeySetup::start_check(const SetupCredentials& credentials)
{
    if (busy() || credentials.api_key.empty() || !setup_provider_supported(credentials.provider))
        return false;

    OpenAIResponsesConfig config;
    config.api_key = credentials.api_key;
    if (!credentials.model.empty())
        config.model = credentials.model;
    if (!m_endpoint_override.empty())
        config.endpoint = m_endpoint_override;
    if (!credentials.endpoint.empty())
        config.endpoint = credentials.endpoint;

    auto candidate = std::make_unique<OpenAIResponsesAgent>(std::move(config), m_transport_factory());
    if (!candidate->ready())
        return false;

    m_started = m_clock();
    if (!candidate->start(probe_request()))
        return false;
    m_candidate = std::move(candidate);
    return true;
}

void ProviderKeySetup::cancel()
{
    if (m_candidate)
        m_candidate->cancel();
    m_candidate.reset();
}

std::optional<SetupOutcome> ProviderKeySetup::poll()
{
    if (!m_candidate)
        return std::nullopt;

    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
        switch (event->kind) {
        case AgentEventKind::TextDelta:
            break; // What it says is irrelevant; that it answers is the test.
        case AgentEventKind::ToolCall:
        case AgentEventKind::Completed:
            // Either way the provider accepted the credentials and replied.
            return finish_ok();
        case AgentEventKind::Failed: {
            SetupOutcome outcome;
            outcome.error =
                event->error.value_or(AgentError{"setup_failed", "The provider did not answer.", true});
            outcome.elapsed_ms = elapsed_ms();
            cancel();
            return outcome;
        }
        }
    }
    return std::nullopt;
}

bool ProviderKeySetup::commit(const SetupCredentials& credentials)
{
    return m_commit && m_commit(credentials);
}

int ProviderKeySetup::elapsed_ms() const
{
    return static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(m_clock() - m_started).count());
}

SetupOutcome ProviderKeySetup::finish_ok()
{
    SetupOutcome outcome;
    outcome.ok         = true;
    outcome.elapsed_ms = elapsed_ms();
    // Drop the probe turn so the verified service is handed over idle, with
    // no partial response left for the user's first real message to inherit.
    m_candidate->cancel();
    outcome.service = std::move(m_candidate);
    m_candidate.reset();
    return outcome;
}

} // namespace Slic3r::GUI::JusPrin::Agent
---CONFIG---
#include "AgentConfiguration.hpp"

#include "OpenAIResponsesAgent.hpp"
#include "libslic3r/AppConfig.hpp"

#include <boost/log/trivial.hpp>

#include <cstdlib>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

constexpr const char* kSection = "jusprin_agent";

std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }

bool configured_true(const AppConfig* config, const char* key)
{
    if (config == nullptr)
        return false;
    const std::string value = config->get(kSection, key);
    return value == "true" || value == "1";
}

} // namespace

std::string load_provider_api_key(const AppConfig* config, const std::string& provider)
{
    return config == nullptr ? std::string() : config->get(kSection, api_key_item_for(provider));
}

AgentRuntime load_agent_runtime(AppConfig* config)
{
    AgentRuntime runtime;
    runtime.setup = make_agent_setup(config);
    runtime.provider = config == nullptr ? std::string() : config->get(kSection, "provider");
    if (runtime.provider.empty())
        runtime.provider = "openai";

    if (!configured_true(config, "enabled")) {
        runtime.unavailable_reason = "The Agent is not enabled.";
        return runtime;
    }
    if (runtime.provider != "openai") {
        runtime.unavailable_reason = "The configured Agent provider is not supported.";
        return runtime;
    }
    if (!configured_true(config, "cloud_consent")) {
        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
        return runtime;
    }

    OpenAIResponsesConfig openai;
    openai.api_key = load_provider_api_key(config, runtime.provider);
    if (config != nullptr && !config->get(kSection, "model").empty())
        openai.model = config->get(kSection, "model");
    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
        openai.endpoint = endpoint;
    // Refused tool calls never reach a card or the activity list; the log is
    // where a wrong call can be read afterwards.
    openai.refusal_listener = [](const std::string& tool, const std::string& arguments, const std::string& code) {
        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
    };
    if (openai.api_key.empty()) {
        runtime.unavailable_reason = "No OpenAI API key is configured.";
        return runtime;
    }
    runtime.service = std::make_unique<OpenAIResponsesAgent>(std::move(openai), make_openai_http_transport());
    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
    if (runtime.availability == AgentAvailability::Unavailable)
        runtime.unavailable_reason = "The OpenAI Agent could not be initialized.";
    return runtime;
}

AgentSetupServicePtr make_agent_setup(AppConfig* config)
{
    // Committing is the only part of setup that touches the machine, so it
    // lives here rather than in the GUI-free probe. Reaching this point means
    // the user read what the dock says about the provider billing them and
    // about the key staying on this machine, and chose to continue: that is
    // the cloud consent load_agent_runtime() requires on the next launch.
    auto commit = [config](const SetupCredentials& credentials) {
        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
            return false;
        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
        config->set(kSection, "provider", credentials.provider);
        config->set(kSection, "enabled", "true");
        config->set(kSection, "cloud_consent", "true");
        if (!credentials.model.empty())
            config->set(kSection, "model", credentials.model);
        // Written now, not at the next routine save, so a crash after setup
        // does not lose a key the user was just told is stored.
        config->save();
        return true;
    };
    std::string endpoint_override;
    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
        endpoint_override = endpoint;
    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit),
                                              std::move(endpoint_override));
}

} // namespace Slic3r::GUI::JusPrin::Agent

---TESTS-CLAUDE---
# CLAUDE.md - Testing Guide for OrcaSlicer

This guide provides comprehensive instructions for Claude Code when writing, maintaining, and understanding tests in the OrcaSlicer codebase.

## ⚠️ CRITICAL RULES - MUST FOLLOW

### 1. **SECTIONS IN LOOPS - NEVER REUSE NAMES**
❌ **WRONG**: Will cause unpredictable behavior
```cpp
TEST_CASE("Bad loop sections") {
    for (int i = 0; i < 3; ++i) {
        SECTION("Same name") {  // WRONG! Same name used multiple times
            REQUIRE(i >= 0);
        }
    }
}
```

✅ **CORRECT**: Use DYNAMIC_SECTION or incorporate counter
```cpp
TEST_CASE("Good loop sections") {
    for (int i = 0; i < 3; ++i) {
        DYNAMIC_SECTION("Section " << i) {  // Unique name per iteration
            REQUIRE(i >= 0);
        }
    }
}
```

### 2. **THREAD SAFETY - ASSERTIONS ARE NOT THREAD-SAFE**
❌ **WRONG**: Will cause undefined behavior or crashes
```cpp
TEST_CASE("Multi-threaded test") {
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back([]() {
            REQUIRE(some_calculation() == expected);  // NOT THREAD-SAFE!
        });
    }
}
```

✅ **CORRECT**: Synchronize results, test on main thread
```cpp
TEST_CASE("Multi-threaded test") {
    std::vector<std::thread> threads;
    std::atomic<int> passed{0};

    for (int i = 0; i < 4; ++i) {
        threads.emplace_back([&passed]() {
            if (some_calculation() == expected) {
                passed++;
            }
        });
    }

    for (auto& t : threads) t.join();
    REQUIRE(passed == 4);  // Test results on main thread
}
```

### 3. **EXPRESSION DECOMPOSITION - AVOID BINARY OPERATORS**
❌ **WRONG**: Cannot decompose properly
```cpp
REQUIRE(a > 0 && b < 10);  // Shows "false" on failure, not individual values
```

✅ **CORRECT**: Split into separate assertions
```cpp
REQUIRE(a > 0);
REQUIRE(b < 10);  // Each shows individual values on failure
```

### 4. **FLOATING POINT - NEVER USE APPROX**
❌ **WRONG**: Approx is deprecated and asymmetric
```cpp
REQUIRE(calculated_value == Catch::Approx(expected));  // Deprecated!
```

✅ **CORRECT**: Use floating point matchers
```cpp
REQUIRE_THAT(calculated_value, WithinAbs(expected, 0.001));
REQUIRE_THAT(calculated_value, WithinRel(expected, 0.01));  // 1% tolerance
REQUIRE_THAT(calculated_value, WithinULP(expected, 4));     // 4 ULPs apart
```

### 5. **TEST ORDERING - ALWAYS USE RANDOM ORDER**
✅ **REQUIRED**: For CI/CD and development
```bash
# Essential flags for running tests
./tests --order rand --warn NoAssertions

# For test sharding (parallel execution), share random seed
./tests --order rand --shard-index 0 --shard-count 3 --rng-seed 0xBEEF
./tests --order rand --shard-index 1 --shard-count 3 --rng-seed 0xBEEF
./tests --order rand --shard-index 2 --shard-count 3 --rng-seed 0xBEEF
```

## Overview of OrcaSlicer's Testing Framework

OrcaSlicer uses **Catch2 v3** (currently v3.11.0, vendored in `tests/catch2/`) as its primary testing framework. The test suite is organized into several modules that mirror the project's architectural components:

> **Note**: Test files include the framework via `#include <catch2/catch_all.hpp>` (the v3 single-header convenience include). All v3 features described in this guide are available.

### Test Structure
```
tests/
├── CMakeLists.txt              # Main test configuration
├── catch_main.hpp              # Custom test reporter
├── libslic3r/                  # Core library tests (21 test files)
├── fff_print/                  # FFF printing tests (12 test files)
├── sla_print/                  # SLA printing tests (4 test files)
├── libnest2d/                  # 2D nesting tests
├── slic3rutils/               # Utility tests
├── data/                      # Test data files and meshes
└── catch2/                    # Catch2 framework files
```

### Build Integration
- Tests are built using CMake with `catch_discover_tests()` integration
- Each test module creates a separate executable (e.g., `libslic3r_tests`, `fff_print_tests`)
- Test data directory is available via `TEST_DATA_DIR` preprocessor definition
- Custom verbose console reporter provides detailed test output

## Test Suite Organization

### libslic3r Tests
Core slicing engine tests covering:
- **Geometry operations**: Points, polygons, lines, Voronoi diagrams
- **File formats**: STL, 3MF, AMF parsing and validation
- **Algorithms**: Clipper operations, mesh boolean operations, optimization
- **Configuration**: Print settings validation and parsing
- **Utilities**: String processing, time utilities, data structures

### fff_print Tests
Fused Filament Fabrication specific tests:
- **G-code generation**: Writer functionality, cooling, lift/unlift
- **Slicing algorithms**: Layer generation, infill patterns
- **Print mechanics**: Flow calculations, extrusion, support material
- **Model processing**: Print objects, skirt/brim generation

### sla_print Tests
Stereolithography specific tests:
- **SLA print processing**: Layer curing, support generation
- **Raycast operations**: Light path calculations
- **Test utilities**: SLA-specific helper functions

## Writing New Tests - Best Practices

### File Organization
1. **Naming Convention**: `test_<feature>.cpp` (e.g., `test_geometry.cpp`)
2. **Header Structure**: Include `<catch2/catch_all.hpp>` first, then relevant headers
3. **Namespace Usage**: Use `using namespace Slic3r;` for convenience
4. **File Placement**: Add to appropriate test directory and update CMakeLists.txt

### Test Naming and Structure
```cpp
#include <catch2/catch_all.hpp>
#include "libslic3r/Point.hpp"

using namespace Slic3r;

TEST_CASE("Feature description", "[category_tag]") {
    // Test implementation
}
```

### Tagging System
Use descriptive tags for test categorization:
- `[Geometry]` - Geometric operations and calculations
- `[GCodeWriter]` - G-code generation functionality  
- `[Config]` - Configuration and settings tests
- `[FileFormat]` - File I/O operations (STL, 3MF, etc.)
- `[Algorithm]` - Core algorithms and processing
- `[Performance]` - Performance benchmarks (if applicable)

## Catch2 Features Guide

### Basic Assertions
```cpp
// Primary assertions - stop test on failure
REQUIRE(expression);
REQUIRE_FALSE(expression);

// Continuing assertions - continue test after failure  
CHECK(expression);
CHECK_FALSE(expression);

// Non-failing checks - record result but don't fail test
CHECK_NOFAIL(expression);  // Useful for assumptions that might be violated
```

### Exception Testing
```cpp
// Verify no exception is thrown
REQUIRE_NOTHROW(function_call());

// Verify any exception is thrown
REQUIRE_THROWS(risky_function());

// Verify specific exception type
REQUIRE_THROWS_AS(function_call(), SpecificException);

// Verify exception message
REQUIRE_THROWS_WITH(function_call(), "Expected error message");

// Verify exception with matchers (for partial matching)
REQUIRE_THROWS_MATCHES(function_call(), SpecificException, 
                       Catch::Matchers::Message("contains this"));
```

### Complex Assertions with Matchers
```cpp
#include <catch2/matchers/catch_matchers.hpp>

// String matchers
using Catch::Matchers::StartsWith;
using Catch::Matchers::EndsWith;
using Catch::Matchers::ContainsSubstring;
using Catch::Matchers::Equals;
using Catch::Matchers::Matches;  // Regex matching

REQUIRE_THAT(result_string, StartsWith("Expected prefix"));
REQUIRE_THAT(result_string, ContainsSubstring("middle part"));
REQUIRE_THAT(result_string, Matches(".*pattern.*"));

// Floating point matchers - ALWAYS use these instead of Approx!
using Catch::Matchers::WithinAbs;
using Catch::Matchers::WithinRel;
using Catch::Matchers::WithinULP;

REQUIRE_THAT(float_value, WithinAbs(expected, 0.001));     // Absolute tolerance
REQUIRE_THAT(float_value, WithinRel(expected, 0.01));      // Relative tolerance (1%)
REQUIRE_THAT(float_value, WithinULP(expected, 4));         // ULP difference (requires IEEE-754)

// Combining matchers
REQUIRE_THAT(value, WithinRel(expected, 0.001) || WithinAbs(0.0, 0.000001));
```

### Sections for Test Organization
```cpp
TEST_CASE("Complex feature testing", "[Feature]") {
    // Common setup code
    SomeObject obj;

    SECTION("First scenario") {
        // Specific test case
        REQUIRE(obj.method1() == expected_value);
    }

    SECTION("Second scenario") {
        // Another test case with same setup
        REQUIRE(obj.method2() == other_expected);
    }
}
```

### BDD-Style Tests
Use for complex scenarios and user story testing:

> **Note**: BDD macros are aliases for TEST_CASE and SECTION with prefixed names
```cpp
SCENARIO("User performs complex operation", "[UserStory]") {
    GIVEN("A specific setup condition") {
        GCodeWriter writer;
        // Setup code

        WHEN("User performs action") {
            auto result = writer.some_operation();

            THEN("Expected outcome occurs") {
                REQUIRE(result.size() > 0);

                AND_WHEN("Follow-up action occurs") {
                    auto next_result = writer.next_operation();

                    THEN("Final outcome is correct") {
                        REQUIRE(next_result == expected);
                    }
                }
            }
        }
    }
}
```

### Data Generators for Parameterized Tests
```cpp
TEST_CASE("Function works with various inputs", "[Algorithm]") {
    auto test_value = GENERATE(1, 3, 5, 7, 11, 13);

    REQUIRE(is_odd(test_value));
    REQUIRE(test_value > 0);
}

// Range-based generators
TEST_CASE("Range testing", "[Algorithm]") {
    auto i = GENERATE(range(1, 10));  // 1 to 9
    REQUIRE(process_value(i) > i);
}

// Using variables in generators (requires GENERATE_COPY or GENERATE_REF)
TEST_CASE("Generator with variables", "[Algorithm]") {
    std::vector<int> values = {1, 2, 3, 4, 5};
    auto test_value = GENERATE_REF(from_range(values));  // Use GENERATE_REF for references

    REQUIRE(test_value > 0);
}

// Custom generators
TEST_CASE("Random values", "[Algorithm]") {
    auto random_int = GENERATE(take(100, random(-1000, 1000)));  // 100 random values
    REQUIRE(process_random_value(random_int));
}
```

### Test Fixtures
```cpp
class GeometryFixture {
public:
    Point origin{0, 0};
    Point unit_x{1, 0};
    Point unit_y{0, 1};

    mutable double tolerance = EPSILON;  // Use mutable for data that might change
};

// Standard fixture - new instance per test run
TEST_CASE_METHOD(GeometryFixture, "Point operations", "[Geometry]") {
    REQUIRE(origin.distance_to(unit_x) == 1.0);
}

// Persistent fixture - single instance for entire test case (v3.2.0+)
TEST_CASE_PERSISTENT_FIXTURE(GeometryFixture, "Persistent operations", "[Geometry]") {
    static int call_count = 0;
    ++call_count;
    INFO("This fixture persists across sections, call: " << call_count);

    SECTION("First section") {
        REQUIRE(origin.distance_to(unit_x) == 1.0);
    }

    SECTION("Second section") {
        REQUIRE(origin.distance_to(unit_y) == 1.0);
        // call_count will be 2 here with persistent fixture
    }
}

// Template fixtures for type-parameterized tests
template<typename T>
class NumericFixture {
public:
    T zero = T{0};
    T one = T{1};
};

TEMPLATE_TEST_CASE_METHOD(NumericFixture, "Numeric operations", "[Template]", int, float, double) {
